/* vNN.xx, UI REDESIGN ui5q2q (his #50, from the AAA judge of the title shot): THE NAME IS THE BIGGEST THING ON THE TITLE. PILLAGERS
   was 64px, under-scaled for a title screen and about the size of a window heading at 4K. It is 104px now with a short amber rule
   under it, the way the shooters he named sign their front screens. A small screen keeps its own smaller size (v8.88). */
#root #title .wordmark{ font-size:104px; line-height:.95; }
#root #title .wordmark::after{ content:''; display:block; width:72px; height:4px; margin:14px auto 0; background:var(--acc); border-radius:1px; }
