check:
{v:'VER',what:'his #50 (UI redesign ui5q2q): the PILLAGERS name on the title is at least 96px with an amber rule under it',
 run:function(){
   var w=document.querySelector('#title .wordmark'); if(!w) return 'no title name';
   var fs=parseFloat(getComputedStyle(w).fontSize), a=getComputedStyle(w,'::after');
   if(window.matchMedia&&window.matchMedia('(max-height: 820px)').matches&&fs<96) return 'SKIP: a small screen keeps its own title size';
   if(fs<96) return 'the title name is '+fs+'px';
   if(!a||a.content==='none'||parseFloat(a.height)<2) return 'no rule under the title name';
   return null; }},
